import com.sap.gateway.ip.core.customdev.util.Messageimport java.time.LocalDateimport java.time.ZoneIdimport javax.xml.parsers.SAXParserFactoryimport java.io.Reader// Secure XmlSlurper setup to disable DOCTYPE and external entity processingdef safeXmlSlurper() {    SAXParserFactory factory = SAXParserFactory.newInstance()    factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true)    factory.setFeature("http://xml.org/sax/features/external-general-entities", false)    factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false)    factory.setNamespaceAware(false)    // DO NOT import groovy.xml.XmlSlurper explicitly.    // In SAP CPI, it's globally available    return new XmlSlurper(factory.newSAXParser().XMLReader)}// Helper: returns true if string date matches current month/yearboolean isCurrentMonth(String dateStr) {    if (!dateStr?.trim()) {        return false    }    try {        String justDate = dateStr.contains('T') ? dateStr.split('T')[0] : dateStr        LocalDate d = LocalDate.parse(justDate)        LocalDate now = LocalDate.now(ZoneId.of("UTC"))        return (d.getYear() == now.getYear() && d.getMonth() == now.getMonth())    } catch(Exception e) {        return false    }}// Main entry point for the scriptdef Message processData(Message message) {    // Get the body as a Reader for streaming    Reader reader = message.getBody(Reader)    def root = safeXmlSlurper().parse(reader)    int totalCount = 0    // Loop over each EmpEmployment    root.'**'.findAll { it.name() == 'EmpEmployment' }.each { emp ->        def dates = []        // direct children of EmpEmployment        dates << emp.originalStartDate?.text()        dates << emp.endDate?.text()        dates << emp.startDate?.text()        // Nested: homeAddressNavDEFLT/startDate        def homeAddrStart = emp.personNav?.PerPerson?.homeAddressNavDEFLT?.PerAddressDEFLT?.startDate?.text()        dates << homeAddrStart        // Nested: jobInfoNav/EmpJob/startDate, workscheduleCodeNav/WorkSchedule/startingDate        emp.jobInfoNav?.EmpJob?.each { job ->            dates << job.startDate?.text()            dates << job.workscheduleCodeNav?.WorkSchedule?.startingDate?.text()        }        // Nested: compInfoNav/EmpCompensation/startDate        dates << emp.compInfoNav?.EmpCompensation?.startDate?.text()        if (dates.any { isCurrentMonth(it) }) {            totalCount += 1        }    }    message.setProperty("ChangedRecordsCount", totalCount)    return message}